add_action('wp_head', 'doma_google_consent_mode_v2', -999);
function doma_google_consent_mode_v2() {
    ?>
<script>
(function () {
  window.dataLayer = window.dataLayer || [];
  function gtag() { dataLayer.push(arguments); }

  gtag('consent', 'default', {
    'ad_storage': 'denied',
    'analytics_storage': 'denied',
    'ad_user_data': 'denied',
    'ad_personalization': 'denied',
    'functionality_storage': 'granted',
    'personalization_storage': 'denied',
    'security_storage': 'granted',
    'wait_for_update': 500
  });

  function domaConsentFromEvent(e) {
    var cats = (e && e.detail && e.detail.categories) ? e.detail.categories : [];
    cats = Array.isArray(cats) ? cats : [];
    var marketing = cats.indexOf('marketing') !== -1;
    var statistics = cats.indexOf('statistics') !== -1;
    var preferences = cats.indexOf('preferences') !== -1;
    return {
      'ad_storage': marketing ? 'granted' : 'denied',
      'analytics_storage': statistics ? 'granted' : 'denied',
      'ad_user_data': marketing ? 'granted' : 'denied',
      'ad_personalization': marketing ? 'granted' : 'denied',
      'personalization_storage': preferences ? 'granted' : 'denied'
    };
  }

  document.addEventListener('cmplz_fire_categories', function (e) {
    gtag('consent', 'update', domaConsentFromEvent(e));
  });

  document.addEventListener('cmplz_revoke', function (e) {
    gtag('consent', 'update', domaConsentFromEvent(e));
  });
})();
</script>
